mapper.select:
SELECT a.*, info.title, info.content, info.publish_time, info.summary, info.receiver_scope, info.status, info.remark, info.receiver_id, info.create_by nick_name, info.publisher publisherId, info.sending_settings sendingSettings FROM sys_message_notice a left join sys_message_info info on a.msg_id = info.id
AND info.status = #{condition.status}
AND info.title like concat('%',#{condition.title}, '%')
AND a.type = #{condition.type}
AND a.type_id = #{condition.typeId}
ORDER BY info.create_time DESC

SELECT a.*, info.title, info.content, info.publish_time, info.summary, info.receiver_scope, info.status, info.remark, info.receiver_id, info.create_by nick_name, info.publisher publisherId FROM sys_message_notice a left join sys_message_info info on a.msg_id = info.id
AND info.status = #{condition.status}
AND info.title like concat('%',#{condition.title}, '%')
AND a.type = #{condition.type}
ORDER BY info.create_time DESC
